fun topologicalSort(n: Int, edges: Array<IntArray>): List<Int> {
    val graph = List(n) { mutableListOf<Int>() }
    val indegree = IntArray(n)
    for ((u, v) in edges) {                          // edge u -> v: u comes before v
        graph[u].add(v)
        indegree[v]++
    }

    val queue = ArrayDeque<Int>()
    for (i in 0 until n) {
        if (indegree[i] == 0) queue.addLast(i)       // nodes with no prerequisites
    }

    val order = mutableListOf<Int>()
    while (queue.isNotEmpty()) {
        val node = queue.removeFirst()
        order.add(node)
        for (next in graph[node]) {
            indegree[next]--                         // one prerequisite is now done
            if (indegree[next] == 0) queue.addLast(next)
        }
    }
    return if (order.size == n) order else emptyList()   // fewer than n means a cycle
}
// Time: O(V + E)   Space: O(V + E)

fun topologicalSortDfs(n: Int, edges: Array<IntArray>): List<Int> {
    val graph = List(n) { mutableListOf<Int>() }
    for ((u, v) in edges) graph[u].add(v)

    val state = IntArray(n)                          // 0 = unvisited, 1 = on current path, 2 = finished
    val order = ArrayList<Int>()

    fun dfs(node: Int): Boolean {                    // returns false when a cycle is found
        if (state[node] == 1) return false           // back edge: cycle
        if (state[node] == 2) return true            // already handled
        state[node] = 1
        for (next in graph[node]) {
            if (!dfs(next)) return false
        }
        state[node] = 2
        order.add(node)                              // added after all its dependents
        return true
    }

    for (i in 0 until n) {
        if (state[i] == 0 && !dfs(i)) return emptyList()
    }
    order.reverse()                                  // reverse postorder is a topological order
    return order
}
// Time: O(V + E)   Space: O(V + E)

fun topologicalLevels(n: Int, edges: Array<IntArray>): Int {
    val graph = List(n) { mutableListOf<Int>() }
    val indegree = IntArray(n)
    for ((u, v) in edges) {
        graph[u].add(v)
        indegree[v]++
    }
    val queue = ArrayDeque<Int>()
    for (i in 0 until n) if (indegree[i] == 0) queue.addLast(i)

    var rounds = 0
    var processed = 0
    while (queue.isNotEmpty()) {
        rounds++                                     // everything in the queue can run in parallel
        repeat(queue.size) {
            val node = queue.removeFirst()
            processed++
            for (next in graph[node]) {
                indegree[next]--
                if (indegree[next] == 0) queue.addLast(next)
            }
        }
    }
    return if (processed == n) rounds else -1        // -1 means a cycle
}
// Time: O(V + E)   Space: O(V + E)

import java.util.PriorityQueue

fun smallestTopologicalOrder(n: Int, edges: Array<IntArray>): List<Int> {
    val graph = List(n) { mutableListOf<Int>() }
    val indegree = IntArray(n)
    for ((u, v) in edges) {
        graph[u].add(v)
        indegree[v]++
    }
    val heap = PriorityQueue<Int>()                  // always pick the smallest available node
    for (i in 0 until n) if (indegree[i] == 0) heap.add(i)

    val order = mutableListOf<Int>()
    while (heap.isNotEmpty()) {
        val node = heap.poll()
        order.add(node)
        for (next in graph[node]) {
            indegree[next]--
            if (indegree[next] == 0) heap.add(next)
        }
    }
    return if (order.size == n) order else emptyList()
}
// Time: O((V + E) log V)   Space: O(V + E)

fun canFinish(numCourses: Int, prerequisites: Array<IntArray>): Boolean {
    val graph = List(numCourses) { mutableListOf<Int>() }
    val indegree = IntArray(numCourses)
    for ((course, pre) in prerequisites) {
        graph[pre].add(course)                       // pre must come before course
        indegree[course]++
    }
    val queue = ArrayDeque<Int>()
    for (i in 0 until numCourses) if (indegree[i] == 0) queue.addLast(i)

    var taken = 0
    while (queue.isNotEmpty()) {
        val c = queue.removeFirst()
        taken++
        for (next in graph[c]) {
            indegree[next]--
            if (indegree[next] == 0) queue.addLast(next)
        }
    }
    return taken == numCourses
}
// Time: O(V + E)   Space: O(V + E)

fun findOrder(numCourses: Int, prerequisites: Array<IntArray>): IntArray {
    val graph = List(numCourses) { mutableListOf<Int>() }
    val indegree = IntArray(numCourses)
    for ((course, pre) in prerequisites) {
        graph[pre].add(course)
        indegree[course]++
    }
    val queue = ArrayDeque<Int>()
    for (i in 0 until numCourses) if (indegree[i] == 0) queue.addLast(i)

    val order = mutableListOf<Int>()
    while (queue.isNotEmpty()) {
        val c = queue.removeFirst()
        order.add(c)
        for (next in graph[c]) {
            indegree[next]--
            if (indegree[next] == 0) queue.addLast(next)
        }
    }
    return if (order.size == numCourses) order.toIntArray() else intArrayOf()
}
// Time: O(V + E)   Space: O(V + E)

fun alienOrder(words: Array<String>): String {
    val graph = HashMap<Char, MutableSet<Char>>()
    val indegree = HashMap<Char, Int>()
    for (w in words) {
        for (c in w) {
            graph.getOrPut(c) { mutableSetOf() }
            indegree.getOrPut(c) { 0 }               // every letter is a node
        }
    }

    // each adjacent pair of words gives at most one ordering rule
    for (i in 0 until words.size - 1) {
        val a = words[i]
        val b = words[i + 1]
        if (a.length > b.length && a.startsWith(b)) return ""   // invalid input
        val len = minOf(a.length, b.length)
        for (j in 0 until len) {
            if (a[j] != b[j]) {
                if (graph[a[j]]!!.add(b[j])) {                  // avoid counting a duplicate edge
                    indegree[b[j]] = indegree[b[j]]!! + 1
                }
                break                                            // only the first difference matters
            }
        }
    }

    val queue = ArrayDeque<Char>()
    for ((c, d) in indegree) if (d == 0) queue.addLast(c)

    val sb = StringBuilder()
    while (queue.isNotEmpty()) {
        val c = queue.removeFirst()
        sb.append(c)
        for (next in graph[c]!!) {
            indegree[next] = indegree[next]!! - 1
            if (indegree[next] == 0) queue.addLast(next)
        }
    }
    return if (sb.length == indegree.size) sb.toString() else ""   // shorter means a cycle
}
// Time: O(total characters + alphabet²)   Space: O(alphabet)

fun minimumSemesters(n: Int, relations: Array<IntArray>): Int {
    val graph = List(n + 1) { mutableListOf<Int>() }          // courses are 1-indexed
    val indegree = IntArray(n + 1)
    for ((prev, next) in relations) {
        graph[prev].add(next)
        indegree[next]++
    }
    val queue = ArrayDeque<Int>()
    for (i in 1..n) if (indegree[i] == 0) queue.addLast(i)

    var semesters = 0
    var taken = 0
    while (queue.isNotEmpty()) {
        semesters++                                            // one BFS level is one semester
        repeat(queue.size) {
            val course = queue.removeFirst()
            taken++
            for (nxt in graph[course]) {
                indegree[nxt]--
                if (indegree[nxt] == 0) queue.addLast(nxt)
            }
        }
    }
    return if (taken == n) semesters else -1
}
// Time: O(V + E)   Space: O(V + E)

fun minimumTime(n: Int, relations: Array<IntArray>, time: IntArray): Int {
    val graph = List(n + 1) { mutableListOf<Int>() }
    val indegree = IntArray(n + 1)
    for ((prev, next) in relations) {
        graph[prev].add(next)
        indegree[next]++
    }
    val finish = IntArray(n + 1)                               // earliest finish time of each course
    val queue = ArrayDeque<Int>()
    for (i in 1..n) {
        if (indegree[i] == 0) {
            queue.addLast(i)
            finish[i] = time[i - 1]
        }
    }

    var answer = 0
    while (queue.isNotEmpty()) {
        val node = queue.removeFirst()
        answer = maxOf(answer, finish[node])
        for (next in graph[node]) {
            // a course starts when its slowest prerequisite finishes
            finish[next] = maxOf(finish[next], finish[node] + time[next - 1])
            indegree[next]--
            if (indegree[next] == 0) queue.addLast(next)
        }
    }
    return answer
}
// Time: O(V + E)   Space: O(V + E)
// This is the longest path in a DAG, computed in topological order

fun findMinHeightTrees(n: Int, edges: Array<IntArray>): List<Int> {
    if (n == 1) return listOf(0)
    val graph = List(n) { mutableSetOf<Int>() }
    for ((a, b) in edges) {
        graph[a].add(b)
        graph[b].add(a)
    }
    var leaves = (0 until n).filter { graph[it].size == 1 }
    var remaining = n
    while (remaining > 2) {                                    // the center has 1 or 2 nodes
        remaining -= leaves.size
        val newLeaves = mutableListOf<Int>()
        for (leaf in leaves) {
            val neighbor = graph[leaf].first()
            graph[neighbor].remove(leaf)
            if (graph[neighbor].size == 1) newLeaves.add(neighbor)
        }
        leaves = newLeaves
    }
    return leaves
}
// Time: O(n)   Space: O(n)
// Same layer-by-layer idea as Kahn's, applied to an undirected tree

fun sequenceReconstruction(nums: IntArray, sequences: List<List<Int>>): Boolean {
    val n = nums.size
    val graph = List(n + 1) { mutableListOf<Int>() }
    val indegree = IntArray(n + 1)
    for (seq in sequences) {
        for (i in 0 until seq.size - 1) {
            graph[seq[i]].add(seq[i + 1])
            indegree[seq[i + 1]]++
        }
    }
    val queue = ArrayDeque<Int>()
    for (i in 1..n) if (indegree[i] == 0) queue.addLast(i)

    var index = 0
    while (queue.isNotEmpty()) {
        if (queue.size > 1) return false                       // two choices: not unique
        val node = queue.removeFirst()
        if (nums[index++] != node) return false
        for (next in graph[node]) {
            indegree[next]--
            if (indegree[next] == 0) queue.addLast(next)
        }
    }
    return index == n
}
// Time: O(n + total sequence length)   Space: O(n + total sequence length)
// The order is unique exactly when the queue never holds more than one node

fun findAllRecipes(
    recipes: Array<String>,
    ingredients: List<List<String>>,
    supplies: Array<String>
): List<String> {
    val needs = HashMap<String, MutableList<String>>()         // ingredient -> recipes using it
    val indegree = HashMap<String, Int>()
    for ((i, recipe) in recipes.withIndex()) {
        indegree[recipe] = ingredients[i].size                 // missing ingredients count
        for (ing in ingredients[i]) {
            needs.getOrPut(ing) { mutableListOf() }.add(recipe)
        }
    }

    val recipeSet = recipes.toHashSet()
    val queue = ArrayDeque<String>(supplies.toList())          // start with what we already have
    val result = mutableListOf<String>()
    while (queue.isNotEmpty()) {
        val item = queue.removeFirst()
        if (item in recipeSet) result.add(item)
        for (r in needs[item] ?: emptyList()) {
            indegree[r] = indegree[r]!! - 1
            if (indegree[r] == 0) queue.addLast(r)             // all ingredients available
        }
    }
    return result
}
// Time: O(V + E)   Space: O(V + E)

fun eventualSafeNodes(graph: Array<IntArray>): List<Int> {
    val n = graph.size
    val reverse = List(n) { mutableListOf<Int>() }
    val outdegree = IntArray(n)
    for (u in 0 until n) {
        outdegree[u] = graph[u].size
        for (v in graph[u]) reverse[v].add(u)                  // flip every edge
    }
    val queue = ArrayDeque<Int>()
    for (i in 0 until n) if (outdegree[i] == 0) queue.addLast(i)   // terminal nodes are safe

    val safe = BooleanArray(n)
    while (queue.isNotEmpty()) {
        val node = queue.removeFirst()
        safe[node] = true
        for (prev in reverse[node]) {
            outdegree[prev]--
            if (outdegree[prev] == 0) queue.addLast(prev)      // all its exits lead to safe nodes
        }
    }
    return (0 until n).filter { safe[it] }
}
// Time: O(V + E)   Space: O(V + E)
// Nodes on or leading into a cycle are never added

fun longestIncreasingPath(matrix: Array<IntArray>): Int {
    val rows = matrix.size
    val cols = matrix[0].size
    val dirs = arrayOf(intArrayOf(1, 0), intArrayOf(-1, 0), intArrayOf(0, 1), intArrayOf(0, -1))
    val indegree = Array(rows) { IntArray(cols) }

    // edge from a smaller cell to a larger neighbor
    for (r in 0 until rows) {
        for (c in 0 until cols) {
            for ((dr, dc) in dirs) {
                val nr = r + dr
                val nc = c + dc
                if (nr in 0 until rows && nc in 0 until cols && matrix[nr][nc] < matrix[r][c]) {
                    indegree[r][c]++
                }
            }
        }
    }

    val queue = ArrayDeque<IntArray>()
    for (r in 0 until rows) for (c in 0 until cols) {
        if (indegree[r][c] == 0) queue.addLast(intArrayOf(r, c))
    }

    var length = 0
    while (queue.isNotEmpty()) {
        length++                                               // each layer extends the path by one
        repeat(queue.size) {
            val (r, c) = queue.removeFirst()
            for ((dr, dc) in dirs) {
                val nr = r + dr
                val nc = c + dc
                if (nr in 0 until rows && nc in 0 until cols && matrix[nr][nc] > matrix[r][c]) {
                    indegree[nr][nc]--
                    if (indegree[nr][nc] == 0) queue.addLast(intArrayOf(nr, nc))
                }
            }
        }
    }
    return length
}
// Time: O(rows * cols)   Space: O(rows * cols)
// A DFS with memoization gives the same complexity
